package cli

import (
	"archive/tar"
	"compress/gzip"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func importCmd() *cobra.Command {
	var fromRepo string

	cmd := &cobra.Command{
		Use:   "import [file]",
		Short: "Import workspace from YAML or tarball",
		Long: `Recreate a workspace from an exported YAML or tarball.

  tws import auth-workspace.yaml           # from YAML file
  tws import auth-workspace.tar.gz         # from tarball (includes inject files)
  tws import --from-repo auth              # from .tws/workspaces/auth.yaml`,
		Args: cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			internal.RequireTool("git")

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}

			if fromRepo != "" {
				return importFromRepoE(fromRepo, ws)
			}

			if len(args) == 0 {
				return fmt.Errorf("usage: tws import <file> or tws import --from-repo <feature>")
			}

			file := args[0]
			if strings.HasSuffix(file, ".tar.gz") || strings.HasSuffix(file, ".tgz") {
				return importTarballE(file, ws)
			}
			return importYAMLE(file, ws)
		},
	}

	cmd.Flags().StringVar(&fromRepo, "from-repo", "", "Import from .tws/workspaces/<feature>.yaml")

	return cmd
}

func importFromRepoE(feature string, ws internal.Workspace) error {
	repoRoot, err := internal.MainRepoRoot()
	if err != nil {
		return fmt.Errorf("not inside a git repository")
	}

	path := filepath.Join(repoRoot, ".tws", "workspaces", feature+".yaml")
	return importYAMLE(path, ws)
}

func importYAMLE(file string, ws internal.Workspace) error {
	data, err := os.ReadFile(file)
	if err != nil {
		return fmt.Errorf("reading %s: %w", file, err)
	}

	export, err := internal.UnmarshalExport(data)
	if err != nil {
		return fmt.Errorf("parsing %s: %w", file, err)
	}

	return recreateWorkspaceE(export, "", ws)
}

func importTarballE(file string, ws internal.Workspace) error {
	f, err := os.Open(file)
	if err != nil {
		return fmt.Errorf("opening %s: %w", file, err)
	}
	defer f.Close() //nolint:errcheck

	gr, err := gzip.NewReader(f)
	if err != nil {
		return fmt.Errorf("not a valid gzip file: %w", err)
	}
	defer gr.Close() //nolint:errcheck

	tmpDir, err := os.MkdirTemp("", "tws-import-*")
	if err != nil {
		return err
	}
	defer os.RemoveAll(tmpDir) //nolint:errcheck

	tr := tar.NewReader(gr)
	for {
		header, err := tr.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			return fmt.Errorf("reading tarball: %w", err)
		}

		if isRuntimeState(header.Name) {
			continue
		}
		target, err := safeArchiveTarget(tmpDir, header.Name)
		if err != nil {
			return err
		}
		switch header.Typeflag {
		case tar.TypeDir:
			if err := os.MkdirAll(target, 0755); err != nil {
				return fmt.Errorf("creating archive directory %s: %w", header.Name, err)
			}
		case tar.TypeReg:
			if err := os.MkdirAll(filepath.Dir(target), 0755); err != nil {
				return fmt.Errorf("creating parent for %s: %w", header.Name, err)
			}
			outFile, err := os.OpenFile(target, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0600)
			if err != nil {
				return fmt.Errorf("creating extracted file %s: %w", header.Name, err)
			}
			if _, copyErr := io.Copy(outFile, tr); copyErr != nil {
				_ = outFile.Close()
				return fmt.Errorf("extracting %s: %w", header.Name, copyErr)
			}
			if err := outFile.Close(); err != nil {
				return fmt.Errorf("closing extracted file %s: %w", header.Name, err)
			}
		default:
			return fmt.Errorf("unsupported archive entry %q (type %d)", header.Name, header.Typeflag)
		}
	}

	data, err := os.ReadFile(filepath.Join(tmpDir, "workspace.yaml"))
	if err != nil {
		return fmt.Errorf("tarball missing workspace.yaml")
	}

	export, err := internal.UnmarshalExport(data)
	if err != nil {
		return fmt.Errorf("parsing workspace.yaml: %w", err)
	}

	injectSrc := filepath.Join(tmpDir, "inject")
	return recreateWorkspaceE(export, injectSrc, ws)
}

func safeArchiveTarget(root, name string) (string, error) {
	if name == "" || filepath.IsAbs(name) {
		return "", fmt.Errorf("unsafe archive path %q", name)
	}
	clean := filepath.Clean(filepath.FromSlash(name))
	if clean == "." || clean == ".." || strings.HasPrefix(clean, ".."+string(filepath.Separator)) {
		return "", fmt.Errorf("unsafe archive path %q", name)
	}
	root = filepath.Clean(root)
	target := filepath.Join(root, clean)
	rel, err := filepath.Rel(root, target)
	if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return "", fmt.Errorf("archive path escapes destination: %q", name)
	}
	return target, nil
}

// isRuntimeState returns true for explicit runtime-state paths.
//
// The list is exact-name only, with two deliberate prefix families: every
// `.reparent*` artifact of the safe-reparent transaction — the state file, the
// remote follow-up record and the `.reparent/` scratch tree — is runtime state
// that must never travel in an export or be recreated by an import. They are
// grouped by prefix rather than enumerated because the scratch tree's children
// are run-id-named and cannot be listed. `.session-intents/` is likewise
// token-named, ephemeral and tool-owned. No user file can collide: both
// families are dot-prefixed and reserved.
//
// Any other future runtime-state file MUST be added here explicitly.
func isRuntimeState(path string) bool {
	normalized := filepath.ToSlash(path)
	if reparentPathHasScratchComponent(normalized) {
		return true
	}
	return normalized == ".session-intents" ||
		strings.HasPrefix(normalized, ".session-intents/") ||
		strings.HasPrefix(normalized, ".tws/state/") ||
		normalized == ".tws/state" ||
		normalized == ".sync-state.yaml" ||
		normalized == ".sync-state.v2.yaml" ||
		normalized == ".sync-run.lock"
}

func recreateWorkspaceE(export internal.WorkspaceExport, injectSrc string, ws internal.Workspace) error {
	if ws.Mode == internal.ModeCheckout {
		return recreateCheckout(export, injectSrc, ws)
	}
	return recreateExternal(export, injectSrc)
}

// recreateCheckout imports into checkout mode: restores under .tws/features/,
// creates/registers branches without linked worktrees, never imports runtime state.
func recreateCheckout(export internal.WorkspaceExport, injectSrc string, ws internal.Workspace) error {
	feature := export.Feature
	if err := internal.GuardFeatureName(ws.MetadataRoot, feature); err != nil {
		return err
	}

	featurePath := ws.FeaturePath(feature)

	if err := os.MkdirAll(featurePath, 0755); err != nil {
		return fmt.Errorf("creating feature directory: %w", err)
	}

	// FEATURE.md
	featureMD := filepath.Join(featurePath, "FEATURE.md")
	if _, err := os.Stat(featureMD); os.IsNotExist(err) {
		_ = os.WriteFile(featureMD, []byte("# "+feature+"\n"), 0644)
	}

	// Stack
	if len(export.Stack.Branches) > 0 {
		if err := internal.SaveStack(featurePath, export.Stack); err != nil {
			return fmt.Errorf("writing stack.yaml: %w", err)
		}
		fmt.Printf("  Restored stack.yaml (%d branches)\n", len(export.Stack.Branches))
	}

	// Decisions
	if len(export.Decisions.Entries) > 0 {
		if err := internal.SaveDecisions(featurePath, export.Decisions); err != nil {
			fmt.Printf("Warning: could not write decisions.yaml: %v\n", err)
		} else {
			fmt.Printf("  Restored decisions.yaml (%d entries)\n", len(export.Decisions.Entries))
		}
	}

	// Inject files
	injectDir := internal.InjectPath(featurePath)
	if err := os.MkdirAll(injectDir, 0755); err != nil {
		return fmt.Errorf("creating inject directory: %w", err)
	}
	if injectSrc != "" {
		if _, err := os.Stat(injectSrc); err == nil {
			count, _ := copyDir(injectSrc, injectDir)
			if count > 0 {
				fmt.Printf("  Restored %d inject file(s)\n", count)
			}
		}
	}

	// Register branches (no worktrees in checkout mode)
	for _, entry := range export.Stack.Branches {
		gitBranch := entry.GitBranch()
		if internal.VerifyGitRef(ws.RepoRoot, gitBranch) == nil {
			fmt.Printf("  [=] %s (branch exists: %s)\n", entry.Name, gitBranch)
		} else {
			fmt.Printf("  [-] %s (branch %s not found — fetch from remote first)\n", entry.Name, gitBranch)
		}
	}

	fmt.Printf("Imported feature: %s (checkout mode — no worktrees created)\n", feature)
	return nil
}

// recreateExternal imports into external mode (original behavior).
func recreateExternal(export internal.WorkspaceExport, injectSrc string) error {
	feature := export.Feature
	wsRoot := internal.TwsRoot()
	if err := internal.GuardFeatureName(wsRoot, feature); err != nil {
		return err
	}

	featurePath := internal.FeaturePath(feature)

	if err := internal.EnsureExternalWorkspaceMarker(wsRoot); err != nil {
		return err
	}
	os.MkdirAll(filepath.Join(featurePath, "worktrees"), 0755) //nolint:errcheck

	if _, err := os.Stat(filepath.Join(featurePath, "FEATURE.md")); os.IsNotExist(err) {
		os.WriteFile(filepath.Join(featurePath, "FEATURE.md"), []byte("# "+feature+"\n"), 0644) //nolint:errcheck
	}

	if len(export.Stack.Branches) > 0 {
		if err := internal.SaveStack(featurePath, export.Stack); err != nil {
			fmt.Printf("Warning: could not write stack.yaml: %v\n", err)
		} else {
			fmt.Printf("  Restored stack.yaml (%d branches)\n", len(export.Stack.Branches))
		}
	}

	if len(export.Decisions.Entries) > 0 {
		if err := internal.SaveDecisions(featurePath, export.Decisions); err != nil {
			fmt.Printf("Warning: could not write decisions.yaml: %v\n", err)
		} else {
			fmt.Printf("  Restored decisions.yaml (%d entries)\n", len(export.Decisions.Entries))
		}
	}

	injectDir := internal.InjectPath(featurePath)
	os.MkdirAll(injectDir, 0755) //nolint:errcheck
	if injectSrc != "" {
		if _, err := os.Stat(injectSrc); err == nil {
			count, _ := copyDir(injectSrc, injectDir)
			if count > 0 {
				fmt.Printf("  Restored %d inject file(s)\n", count)
			}
		}
	}

	for _, entry := range export.Stack.Branches {
		path := internal.WorktreePath(feature, entry.Name)
		if _, err := os.Stat(path); err == nil {
			fmt.Printf("  [=] %s (already exists)\n", entry.Name)
			continue
		}

		if internal.BranchExists(entry.Name) {
			err := internal.RunSilent("git", "worktree", "add", "--force", path, entry.Name)
			if err != nil {
				fmt.Printf("  [x] %s (checkout failed)\n", entry.Name)
			} else {
				fmt.Printf("  [+] %s (checked out)\n", entry.Name)
			}
		} else {
			fmt.Printf("  [-] %s (branch not found — fetch from remote first)\n", entry.Name)
		}
	}

	target := internal.ResolveInjectInto("")
	count, err := internal.InjectFilesForFeature(featurePath, target)
	if err != nil {
		return fmt.Errorf("injecting restored files: %w", err)
	}
	if count > 0 {
		fmt.Printf("  Injected files into %d worktree(s)\n", count)
	}

	fmt.Printf("Imported feature: %s\n", feature)
	return nil
}

package cli

import (
	"errors"
	"fmt"
	"os"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func injectCmd() *cobra.Command {
	var into string

	cmd := &cobra.Command{
		Use:   "inject <feature> [branch]",
		Short: "Sync inject/ files into worktrees",
		Long: `Re-sync shared files from inject/ into external linked worktrees.
With no branch, syncs every materialized worktree discovered for the feature,
including logical names that contain slashes. Checkout mode is unsupported
because it has one physical checkout and no linked worktrees.

Injected files are symlinked into the worktree. By default they go to
the worktree root. Use --into to target a subdirectory (e.g., --into .context).

Set inject_into in config to change the default:
  tws config set inject_into .context
  tws config set inject_into .context --repo

Tip: To keep git status clean, either:
  - Add injected filenames to .gitignore (e.g., CLAUDE.local.md)
  - Use --into to target a gitignored subfolder (e.g., --into .context)
  - Or nest inside an already-ignored dir like inject/.claude/`,
		Args: cobra.RangeArgs(1, 2),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			switch len(args) {
			case 0:
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			case 1:
				return internal.ListBranches(args[0]), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			feature := args[0]
			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}
			featurePath, err := internal.ResolveFeaturePathFor(ws, feature)
			if err != nil {
				return err
			}
			if ws.Mode == internal.ModeCheckout {
				return internal.ErrWorktreeUnsupported
			}

			injectDir := internal.InjectPath(featurePath)
			if _, err := os.Stat(injectDir); os.IsNotExist(err) {
				return fmt.Errorf("no inject/ directory found for feature: %s\nCreate it at: %s", feature, injectDir)
			}

			target := internal.ResolveInjectInto(into)

			if len(args) == 2 {
				branch := args[1]
				path, err := internal.ResolveInjectWorktree(featurePath, branch)
				if errors.Is(err, internal.ErrInjectWorktreeNotFound) {
					return fmt.Errorf("worktree not found: %s/%s", feature, branch)
				}
				if err != nil {
					return err
				}
				if err := internal.InjectFiles(featurePath, path, target); err != nil {
					return err
				}
				if target != "" && target != "." {
					fmt.Printf("Injected files into: %s/%s/%s\n", feature, branch, target)
				} else {
					fmt.Printf("Injected files into: %s/%s\n", feature, branch)
				}
			} else {
				count, err := internal.InjectFilesForFeature(featurePath, target)
				if err != nil {
					return err
				}
				fmt.Printf("Injected files into %d worktree(s)\n", count)
			}
			return nil
		},
	}

	cmd.Flags().StringVar(&into, "into", "", "Target subdirectory within worktree (default: root, or inject_into from config)")

	return cmd
}

package cli

import (
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
)

type injectFixture struct {
	root        string
	home        string
	repo        string
	workspace   string
	feature     string
	featurePath string
}

func newInjectFixture(t *testing.T, feature string) *injectFixture {
	t.Helper()

	root := t.TempDir()
	home := filepath.Join(root, "home")
	if err := os.MkdirAll(home, 0755); err != nil {
		t.Fatal(err)
	}
	gitConfig := filepath.Join(root, "gitconfig")
	if err := os.WriteFile(gitConfig, []byte("[user]\n\tname = TWS Inject Test\n\temail = inject@example.test\n\tuseConfigOnly = true\n"), 0600); err != nil {
		t.Fatal(err)
	}
	t.Setenv("HOME", home)
	t.Setenv("GIT_CONFIG_GLOBAL", gitConfig)
	t.Setenv("GIT_CONFIG_NOSYSTEM", "1")
	t.Setenv("GIT_CONFIG_COUNT", "0")

	repo := createInjectRepo(t, root, "primary")
	workspace := filepath.Join(root, "workspace")
	if err := internal.EnsureExternalWorkspaceMarker(workspace); err != nil {
		t.Fatal(err)
	}
	writeInjectTWSConfig(t, home, repo, workspace, "")
	t.Setenv("TWS_ROOT", filepath.Join(root, "decoy-workspace"))

	featurePath := filepath.Join(workspace, feature)
	if err := os.MkdirAll(filepath.Join(featurePath, "inject"), 0755); err != nil {
		t.Fatal(err)
	}

	oldCWD, err := os.Getwd()
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = os.Chdir(oldCWD) })
	if err := os.Chdir(repo); err != nil {
		t.Fatal(err)
	}

	return &injectFixture{
		root:        root,
		home:        home,
		repo:        repo,
		workspace:   workspace,
		feature:     feature,
		featurePath: featurePath,
	}
}

func createInjectRepo(t *testing.T, root, name string) string {
	t.Helper()
	repo := filepath.Join(root, name)
	remote := filepath.Join(root, name+".git")
	injectGit(t, "", "init", "--bare", remote)
	injectGit(t, "", "init", "--initial-branch=main", repo)
	if err := os.WriteFile(filepath.Join(repo, "README.md"), []byte(name+"\n"), 0644); err != nil {
		t.Fatal(err)
	}
	injectGit(t, repo, "add", "README.md")
	injectGit(t, repo, "commit", "-m", "initial")
	injectGit(t, repo, "remote", "add", "origin", remote)
	injectGit(t, repo, "push", "-u", "origin", "main")
	injectGit(t, remote, "symbolic-ref", "HEAD", "refs/heads/main")
	return repo
}

func injectGit(t *testing.T, dir string, args ...string) string {
	t.Helper()
	commandArgs := append([]string{}, args...)
	if dir != "" {
		commandArgs = append([]string{"-C", dir}, commandArgs...)
	}
	cmd := exec.Command("git", commandArgs...)
	cmd.Env = append(os.Environ(),
		"GIT_CONFIG_NOSYSTEM=1",
		"GIT_AUTHOR_NAME=TWS Inject Test",
		"GIT_AUTHOR_EMAIL=inject@example.test",
		"GIT_COMMITTER_NAME=TWS Inject Test",
		"GIT_COMMITTER_EMAIL=inject@example.test",
	)
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("git %v failed: %v\n%s", commandArgs, err, out)
	}
	return strings.TrimSpace(string(out))
}

func writeInjectTWSConfig(t *testing.T, home, repo, workspace, injectInto string) {
	t.Helper()
	configPath := filepath.Join(home, ".config", "tws", "config.yaml")
	if err := os.MkdirAll(filepath.Dir(configPath), 0755); err != nil {
		t.Fatal(err)
	}
	content := fmt.Sprintf("workspaces:\n  %q: %q\n", repo, workspace)
	if canonicalRepo, err := filepath.EvalSymlinks(repo); err == nil && canonicalRepo != repo {
		content += fmt.Sprintf("  %q: %q\n", canonicalRepo, workspace)
	}
	if injectInto != "" {
		content += fmt.Sprintf("inject_into: %q\n", injectInto)
	}
	if err := os.WriteFile(configPath, []byte(content), 0600); err != nil {
		t.Fatal(err)
	}
}

func (f *injectFixture) addWorktree(t *testing.T, repo, logicalName, gitBranch string) string {
	t.Helper()
	if repo == "" {
		repo = f.repo
	}
	injectGit(t, repo, "branch", gitBranch, "main")
	path := filepath.Join(f.featurePath, "worktrees", filepath.FromSlash(logicalName))
	if err := os.MkdirAll(filepath.Dir(path), 0755); err != nil {
		t.Fatal(err)
	}
	injectGit(t, repo, "worktree", "add", path, gitBranch)
	return path
}

func (f *injectFixture) writeInjectFile(t *testing.T, name, content string) string {
	t.Helper()
	path := filepath.Join(f.featurePath, "inject", filepath.FromSlash(name))
	if err := os.MkdirAll(filepath.Dir(path), 0755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(content), 0644); err != nil {
		t.Fatal(err)
	}
	return path
}

func runInjectCommand(t *testing.T, args ...string) (string, error) {
	t.Helper()
	cmd := injectCmd()
	cmd.SilenceErrors = true
	cmd.SilenceUsage = true
	cmd.SetArgs(args)
	var runErr error
	out := captureStdout(t, func() {
		runErr = cmd.Execute()
	})
	return out, runErr
}

func assertRelativeInjectLink(t *testing.T, source, destination, wantContent string) {
	t.Helper()
	info, err := os.Lstat(destination)
	if err != nil {
		t.Fatalf("lstat %s: %v", destination, err)
	}
	if info.Mode()&os.ModeSymlink == 0 {
		t.Fatalf("%s is not a symlink", destination)
	}
	gotTarget, err := os.Readlink(destination)
	if err != nil {
		t.Fatal(err)
	}
	wantTarget, err := filepath.Rel(filepath.Dir(destination), source)
	if err != nil {
		t.Fatal(err)
	}
	if gotTarget != wantTarget {
		t.Fatalf("symlink target = %q, want %q", gotTarget, wantTarget)
	}
	gotContent, err := os.ReadFile(destination)
	if err != nil {
		t.Fatal(err)
	}
	if string(gotContent) != wantContent {
		t.Fatalf("symlink content = %q, want %q", gotContent, wantContent)
	}
}

func assertNotExists(t *testing.T, path string) {
	t.Helper()
	if _, err := os.Lstat(path); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("%s unexpectedly exists or returned a different error: %v", path, err)
	}
}

func copyInjectFile(t *testing.T, source, destination string) {
	t.Helper()
	data, err := os.ReadFile(source)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(filepath.Dir(destination), 0755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(destination, data, 0644); err != nil {
		t.Fatal(err)
	}
}

func TestInjectFeatureWideDiscoversNestedStackWorktrees(t *testing.T) {
	f := newInjectFixture(t, "customer")
	secondary := createInjectRepo(t, f.root, "secondary")

	plain := f.addWorktree(t, "", "plain", "flat-actual")
	nested := f.addWorktree(t, "", "review/team/pr-123", "feat-review/pr-123")
	multiRepo := f.addWorktree(t, secondary, "docs/api", "docs-actual")
	archived := f.addWorktree(t, "", "archive/old", "archive-actual")
	prunable := f.addWorktree(t, "", "stale/prunable", "stale-actual")
	if err := os.RemoveAll(prunable); err != nil {
		t.Fatal(err)
	}

	stack := internal.Stack{Branches: []internal.StackEntry{
		{Name: "missing/not-created", Branch: "missing-actual", Base: "main"},
		{Name: "review/team/pr-123", Branch: "feat-review/pr-123", Base: "plain"},
		{Name: "archive/old", Branch: "archive-actual", Base: "main", Archived: true},
		{Name: "plain", Branch: "flat-actual", Base: "main"},
		{Name: "docs/api", Branch: "docs-actual", Base: "main", Repo: secondary},
		{Name: "stale/prunable", Branch: "stale-actual", Base: "main"},
	}}
	if err := internal.SaveStack(f.featurePath, stack); err != nil {
		t.Fatal(err)
	}

	contextSource := f.writeInjectFile(t, "AGENT_CONTEXT.txt", "shared context\n")
	guideSource := f.writeInjectFile(t, "guides/review.md", "review guide\n")
	if err := os.WriteFile(filepath.Join(plain, "AGENT_CONTEXT.txt"), []byte("local override\n"), 0644); err != nil {
		t.Fatal(err)
	}

	nestedHEAD := injectGit(t, nested, "rev-parse", "HEAD")
	repoSubdir := filepath.Join(f.repo, "nested", "cwd")
	if err := os.MkdirAll(repoSubdir, 0755); err != nil {
		t.Fatal(err)
	}
	if err := os.Chdir(repoSubdir); err != nil {
		t.Fatal(err)
	}

	out, err := runInjectCommand(t, f.feature)
	if err != nil {
		t.Fatalf("feature-wide inject: %v\n%s", err, out)
	}
	if out != "Injected files into 3 worktree(s)\n" {
		t.Fatalf("stdout = %q", out)
	}
	if got := injectGit(t, nested, "rev-parse", "HEAD"); got != nestedHEAD {
		t.Fatalf("nested HEAD changed: %s -> %s", nestedHEAD, got)
	}

	if data, err := os.ReadFile(filepath.Join(plain, "AGENT_CONTEXT.txt")); err != nil || string(data) != "local override\n" {
		t.Fatalf("existing file was not preserved: data=%q err=%v", data, err)
	}
	assertRelativeInjectLink(t, guideSource, filepath.Join(plain, "guides", "review.md"), "review guide\n")
	assertRelativeInjectLink(t, contextSource, filepath.Join(nested, "AGENT_CONTEXT.txt"), "shared context\n")
	assertRelativeInjectLink(t, guideSource, filepath.Join(nested, "guides", "review.md"), "review guide\n")
	assertRelativeInjectLink(t, contextSource, filepath.Join(multiRepo, "AGENT_CONTEXT.txt"), "shared context\n")

	for _, intermediate := range []string{
		filepath.Join(f.featurePath, "worktrees", "review"),
		filepath.Join(f.featurePath, "worktrees", "review", "team"),
		filepath.Join(f.featurePath, "worktrees", "docs"),
	} {
		assertNotExists(t, filepath.Join(intermediate, "AGENT_CONTEXT.txt"))
		assertNotExists(t, filepath.Join(intermediate, "guides"))
	}
	assertNotExists(t, filepath.Join(archived, "AGENT_CONTEXT.txt"))
	assertNotExists(t, filepath.Join(f.root, "decoy-workspace", f.feature, "worktrees", "plain", "AGENT_CONTEXT.txt"))

	for _, branch := range []string{"archive/old", "missing/not-created"} {
		branchOut, branchErr := runInjectCommand(t, f.feature, branch)
		if branchErr == nil {
			t.Fatalf("explicit inject %q unexpectedly succeeded", branch)
		}
		if branchOut != "" {
			t.Fatalf("explicit inject %q printed success-shaped output %q", branch, branchOut)
		}
	}
}

func TestInjectFeatureWideLegacyFallbackUsesOnlyLinkedWorktreeRoots(t *testing.T) {
