// changelogUnreleasedBullets splits CHANGELOG.md's "## Unreleased" section
// into its top-level "- " bulleted items, so callers can assert content
// scoped to one bullet rather than the whole section (which would let two
// merged cells masquerade as three).
func changelogUnreleasedBullets(t *testing.T) []string {
	t.Helper()
	content := readRepoDoc(t, "CHANGELOG.md")
	start := strings.Index(content, "## Unreleased")
	if start < 0 {
		t.Fatal("CHANGELOG.md must have an \"## Unreleased\" section")
	}
	rest := content[start:]
	headingRe := regexp.MustCompile(`(?m)^## `)
	headings := headingRe.FindAllStringIndex(rest, -1)
	block := rest
	if len(headings) >= 2 {
		block = rest[:headings[1][0]]
	}
	bulletRe := regexp.MustCompile(`(?m)^- `)
	locs := bulletRe.FindAllStringIndex(block, -1)
	if len(locs) == 0 {
		t.Fatal("no top-level bullets found in CHANGELOG.md's Unreleased section")
	}
	bullets := make([]string, 0, len(locs))
	for i, loc := range locs {
		end := len(block)
		if i+1 < len(locs) {
			end = locs[i+1][0]
		}
		bullets = append(bullets, block[loc[0]:end])
	}
	return bullets
}

// TestSyncPlanDocs_ChangelogRecoveryCellsAreSeparateItems implements
// spec.md §22.33-i-a: the CHANGELOG.md Unreleased entry must disclose all
// three no-flag recovery cells (cell 1, cell 7, cell 4 — sync_recovery_test.go's
// Case1/Case7/Cell4 coverage) as three separate bullets, each carrying its
// own required content. The spec states plainly that "a check that finds
// cell 1 and cell 7 but not cell 4 fails"; this test encodes that literally
// by asserting each cell's disclosure independently, so dropping any one
// cell's content — or merging two cells into one bullet — fails on its own,
// never masked by the other two passing.
func TestSyncPlanDocs_ChangelogRecoveryCellsAreSeparateItems(t *testing.T) {
	full := strings.ToLower(readRepoDoc(t, "CHANGELOG.md"))
	for _, marker := range []string{"recovery cell 1", "recovery cell 7", "recovery cell 4"} {
		if n := strings.Count(full, marker); n != 1 {
			t.Fatalf("CHANGELOG.md must name %q exactly once, found %d", marker, n)
		}
	}

	bullets := changelogUnreleasedBullets(t)
	find := func(marker string) (int, string) {
		for i, b := range bullets {
			if strings.Contains(strings.ToLower(b), marker) {
				return i, b
			}
		}
		t.Fatalf("no CHANGELOG.md bullet in ## Unreleased names %q", marker)
		return -1, ""
	}

	idx1, bullet1 := find("recovery cell 1")
	idx7, bullet7 := find("recovery cell 7")
	idx4, bullet4 := find("recovery cell 4")

	if idx1 == idx7 || idx1 == idx4 || idx7 == idx4 {
		t.Fatalf("recovery cells 1, 7 and 4 must be three separate CHANGELOG bullets; got bullet indices %d, %d, %d", idx1, idx7, idx4)
	}

	n1 := normalizeProse(bullet1)
	if !strings.Contains(n1, "nothing to abort") || !strings.Contains(n1, "no sync in progress") {
		t.Errorf("cell 1 bullet must disclose the previous \"Nothing to abort — no sync in progress.\" wording:\n%s", bullet1)
	}
	if !strings.Contains(n1, "stale sync guard from pid <pid> cleared; no sync state was present.") {
		t.Errorf("cell 1 bullet must quote the new stale-guard message (normalized):\n%s", bullet1)
	}

	n7 := normalizeProse(bullet7)
	if !strings.Contains(n7, "clears both") {
		t.Errorf("cell 7 bullet must disclose that --abort now clears both artefacts:\n%s", bullet7)
	}
	if !strings.Contains(n7, "sync state cleared; stale sync guard from pid <pid> cleared.") {
		t.Errorf("cell 7 bullet must quote the combined-clear message (normalized):\n%s", bullet7)
	}

	n4 := normalizeProse(bullet4)
	if !strings.Contains(n4, "--continue") || !strings.Contains(n4, "--abort") {
		t.Errorf("cell 4 bullet must name both recovery verbs, --continue and --abort:\n%s", bullet4)
	}
	if !strings.Contains(n4, "the interrupted guarded setup's backup of the previous sync state was discarded") {
		t.Errorf("cell 4 bullet must quote the discard sentence (normalized):\n%s", bullet4)
	}
	if !strings.Contains(n4, "refuses the same residue or discards the backup") {
		t.Errorf("cell 4 bullet must disclose the older-release downgrade note:\n%s", bullet4)
	}
}

// TestSyncPlanDocs_ChangelogCheckoutDowngradeSentenceIsContinueOnly pins the
// one attribution §13.6 rule 5's old-binary table makes and the CHANGELOG
// must not blur: the checkout version-comparison sentence
// `checkout sync transaction state version 3 is newer than 2; upgrade tws or
// remove <path>` is the OLD binary's `--continue` answer alone. A FRESH old
// binary run over the same transaction never reaches that comparison — it
// refuses earlier, at HasCheckoutTransaction, with the shipped
// `previous checkout-sync incomplete; use --continue or --abort`.
//
// A CHANGELOG that attributes the version sentence to "fresh/--continue"
// would tell an operator to expect words a fresh run never prints, so the
// two sentences are asserted to be attributed separately here, and the
// version sentence is asserted NOT to be attributed to a fresh run.
func TestSyncPlanDocs_ChangelogCheckoutDowngradeSentenceIsContinueOnly(t *testing.T) {
	const versionSentence = "checkout sync transaction state version 3 is newer than 2; upgrade tws or remove <path>"
	const freshSentence = "previous checkout-sync incomplete; use --continue or --abort"

	full := normalizeProse(readRepoDoc(t, "CHANGELOG.md"))
	if !strings.Contains(full, strings.ToLower(versionSentence)) {
		t.Fatalf("CHANGELOG.md must quote the checkout downgrade sentence %q", versionSentence)
	}

	bullets := changelogUnreleasedBullets(t)
	var owner string
	for _, b := range bullets {
		if strings.Contains(normalizeProse(b), strings.ToLower(versionSentence)) {
			if owner != "" {
				t.Fatalf("the checkout downgrade sentence must live in exactly one Unreleased bullet")
			}
			owner = normalizeProse(b)
		}
	}
	if owner == "" {
		t.Fatal("no ## Unreleased bullet quotes the checkout downgrade sentence")
	}

	// The version sentence must be attributed to --continue...
	idx := strings.Index(owner, strings.ToLower(versionSentence))
	lead := owner[:idx]
	if !strings.Contains(lead, "--continue") {
		t.Errorf("the checkout downgrade sentence must be attributed to --continue:\n%s", owner)
	}
	// ...and never jointly to a fresh run.
	for _, blurred := range []string{"fresh/--continue", "fresh/`--continue`", "fresh or --continue", "--continue/fresh"} {
		if strings.Contains(owner, blurred) {
			t.Errorf("the checkout downgrade sentence must not be attributed to %q: a fresh run never reaches the version comparison:\n%s", blurred, owner)
		}
	}
	// If the fresh cell is mentioned at all, it must carry its OWN sentence.
	if strings.Contains(owner, "fresh") && !strings.Contains(owner, strings.ToLower(freshSentence)) {
		t.Errorf("a bullet that mentions the fresh checkout cell must quote its own sentence %q:\n%s", freshSentence, owner)
	}
}

// ===========================================================================
// §22.34 — the gate suite is declared, runnable and non-vacuous.
// ===========================================================================

// criterion34GateCommands is §22.34's own list, verbatim: the full gate
// suite, in the spec's order.
var criterion34GateCommands = []string{
	"gofmt -l internal cmd",
	"go test ./... -count=1",
	"go vet ./...",
	"golangci-lint run ./...",
	"make build",
	"git diff --check",
	"tpatch feature deps --validate-all",
}

// criterion34FocusedSelectors is §22.34's "focused gates while implementing"
// block: the -run selectors an implementer is told to use. A selector that
// matches no declared test in the corpus is a documentation lie, so each is
// asserted non-vacuous below.
var criterion34FocusedSelectors = []string{
	"TestRebasePlan|TestPlanFingerprint|TestPlanSchema|TestRemainingRebaseEntries",
	"TestSyncPlan|TestPlanGuard|TestSyncNoFlag_",
	"TestSyncScoped_|TestCheckoutSyncModes_",
}

// declaredTestNames parses every `func TestXxx(` declaration under the two
// packages this feature touches, by scanning the source rather than by
// running anything.
func declaredTestNames(t *testing.T) []string {
	t.Helper()
	re := regexp.MustCompile(`(?m)^func (Test[A-Za-z0-9_]*)\(`)
	var names []string
	for _, dir := range []string{"internal", "internal/cli"} {
		entries, err := os.ReadDir(filepath.Join(docsRepoRoot, dir))
		if err != nil {
			t.Fatalf("read %s: %v", dir, err)
		}
		for _, e := range entries {
			if e.IsDir() || !strings.HasSuffix(e.Name(), "_test.go") {
				continue
			}
			data, err := os.ReadFile(filepath.Join(docsRepoRoot, dir, e.Name()))
			if err != nil {
				t.Fatalf("read %s/%s: %v", dir, e.Name(), err)
			}
			for _, m := range re.FindAllStringSubmatch(string(data), -1) {
				names = append(names, m[1])
			}
		}
	}
	if len(names) == 0 {
		t.Fatal("found no declared test functions at all; the scan is broken")
	}
	return names
}

// TestSyncPlanDocs_Criterion22_34_GateSuiteIsDeclaredAndNonVacuous is
// §22.34's executable owner. The suite itself is run by the outer harness;
// what a test inside the repository can and must own is that every gate the
// criterion names really EXISTS here and that none of its selectors is
// vacuous:
//
//   - `gofmt -l internal cmd` is executed for real and must report nothing;
//   - `make build` names a real Makefile target, and the Makefile also
//     declares the `test` and `lint` targets the suite leans on;
//   - `git diff --check` is executed for real against the working tree;
//   - each focused `-run` selector matches at least one declared test in
//     `internal/` or `internal/cli/`;
//   - the frozen-path gate of criterion 1 still holds: `TestSyncNoFlag_`
//     matches, and the fixture directory still contains exactly 126 files.
//
// A gate command list that drifts from the spec's own block, or a selector
// that stops matching anything, fails here.
func TestSyncPlanDocs_Criterion22_34_GateSuiteIsDeclaredAndNonVacuous(t *testing.T) {
	if len(criterion34GateCommands) != 7 {
		t.Fatalf("§22.34 lists 7 gate commands, this table has %d", len(criterion34GateCommands))
	}

	t.Run("gofmt_reports_nothing", func(t *testing.T) {
		out, err := exec.Command("gofmt", "-l",
			filepath.Join(docsRepoRoot, "internal"), filepath.Join(docsRepoRoot, "cmd")).CombinedOutput()
		if err != nil {
			t.Fatalf("gofmt -l internal cmd: %v\n%s", err, out)
		}
		if strings.TrimSpace(string(out)) != "" {
			t.Fatalf("gofmt -l internal cmd reported unformatted files:\n%s", out)
		}
	})

	t.Run("make_targets_exist", func(t *testing.T) {
		makefile := readRepoDoc(t, "Makefile")
		for _, target := range []string{"build:", "test:", "lint:"} {
			if !regexp.MustCompile(`(?m)^` + regexp.QuoteMeta(target)).MatchString(makefile) {
				t.Fatalf("Makefile declares no %q target, but §22.34's suite invokes it", target)
			}
		}
	})

	t.Run("git_diff_check_is_clean", func(t *testing.T) {
		cmd := exec.Command("git", "diff", "--check")
		cmd.Dir = docsRepoRoot
		if out, err := cmd.CombinedOutput(); err != nil {
			t.Fatalf("git diff --check failed: %v\n%s", err, out)
		}
	})

	t.Run("focused_selectors_are_non_vacuous", func(t *testing.T) {
		names := declaredTestNames(t)
		for _, selector := range criterion34FocusedSelectors {
			re, err := regexp.Compile(selector)
			if err != nil {
				t.Fatalf("selector %q does not compile: %v", selector, err)
			}
			matched := 0
			for _, n := range names {
				if re.MatchString(n) {
					matched++
				}
			}
			if matched == 0 {
				t.Fatalf("focused selector %q matches no declared test: the documented gate is vacuous", selector)
			}
		}
	})

	t.Run("frozen_path_gate_still_holds", func(t *testing.T) {
		names := declaredTestNames(t)
		noflag := 0
		for _, n := range names {
			if strings.HasPrefix(n, "TestSyncNoFlag_") {
				noflag++
			}
		}
		if noflag == 0 {
			t.Fatal("no TestSyncNoFlag_ test is declared; §22 criterion 1's frozen-path gate would be vacuous")
		}
		files := 0
		root := filepath.Join(docsRepoRoot, "internal", "cli", "testdata", "sync_noflag")
		if err := filepath.WalkDir(root, func(_ string, d fs.DirEntry, err error) error {
			if err != nil {
				return err
			}
			if !d.IsDir() {
				files++
			}
			return nil
		}); err != nil {
			t.Fatalf("walk %s: %v", root, err)
		}
		if files != 126 {
			t.Fatalf("internal/cli/testdata/sync_noflag holds %d files, want the frozen 126", files)
		}
	})
}

// ---------------------------------------------------------------------------
// TestSyncPlanDocs_NegativeCheckHasExactlyTwoHalves
// ---------------------------------------------------------------------------

// bannedDocPhrases are the three substrings spec.md §22.33a forbids: an
// unqualified "--plan mutates nothing" claim, a bare `from` scope-value
// spelling, and a ninth warning kind. None of these are flag literals, so
// they are checked separately from TestSyncPlanDocs_FlagWorkflowSurfacesCarryAllFiveLiterals.
var bannedDocPhrases = []string{"without mutating anything", "scope=from", "nine warning"}

// TestSyncPlanDocs_NegativeCheckHasExactlyTwoHalves implements spec.md
// §22.33a's negative check exactly as scoped: "exactly two halves, and no
// third". Half (a) is a corpus grep over README.md, CHANGELOG.md, docs/ and
// assets/ only — never internal/, never cmd/, never a _test.go file, never
// a testdata directory — because tests legitimately contain every banned
// phrase as negative fixtures, so an unscoped grep would forbid the very
// tests that enforce this criterion. Half (b) is the exact tws sync --help
// output, asserted never to contain any of the three phrases as a
// substring.
func TestSyncPlanDocs_NegativeCheckHasExactlyTwoHalves(t *testing.T) {
	t.Run("prose-and-assets", func(t *testing.T) {
		// This walk is built to match the spec's corpus by construction: it
		// only ever reads README.md, CHANGELOG.md and files under docs/ and
		// assets/, and it skips any directory named "testdata" that it
		// encounters. It never touches internal/, cmd/, or any _test.go
		// file — those simply are not among the four roots below.
		roots := []string{
			filepath.Join(docsRepoRoot, "README.md"),
			filepath.Join(docsRepoRoot, "CHANGELOG.md"),
			filepath.Join(docsRepoRoot, "docs"),
			filepath.Join(docsRepoRoot, "assets"),
		}
		var files []string
		for _, root := range roots {
			info, err := os.Stat(root)
			if err != nil {
				t.Fatalf("stat %s: %v", root, err)
			}
			if !info.IsDir() {
				files = append(files, root)
				continue
			}
			if err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
				if err != nil {
					return err
				}
				if d.IsDir() {
					if d.Name() == "testdata" {
						return filepath.SkipDir
					}
					return nil
				}
				files = append(files, path)
				return nil
			}); err != nil {
				t.Fatalf("walking %s: %v", root, err)
			}
		}
		if len(files) < 5 {
			t.Fatalf("corpus walk found only %d files, expected the README, CHANGELOG and docs/+assets/ trees", len(files))
		}

		for _, path := range files {
			data, err := os.ReadFile(path)
			if err != nil {
				t.Fatalf("reading %s: %v", path, err)
			}
			content := string(data)
			for _, phrase := range bannedDocPhrases {
				if strings.Contains(content, phrase) {
					t.Errorf("%s must not contain the banned phrase %q", path, phrase)
				}
			}
		}

		// Positive control: the Go tree legitimately contains a banned
		// phrase as a negative-fixture string (internal/rebase_plan_render_test.go
		// asserts a rendered Policy line never prints "scope=from"). This
		// file is deliberately outside every root above; if it had been
		// included, this exact check would fail — which is the reason
		// spec.md §22.33a scopes the corpus away from the Go tree at all,
		// rather than an assumption this test takes on faith.
		goFixture := filepath.Join("..", "rebase_plan_render_test.go")
		data, err := os.ReadFile(goFixture)
		if err != nil {
			t.Fatalf("reading %s: %v", goFixture, err)
		}
		if !strings.Contains(string(data), "scope=from") {
			t.Fatalf("%s no longer contains the banned literal \"scope=from\" as a negative-fixture string; the corpus-exclusion rationale (spec.md §22.33a) has nothing left to guard against", goFixture)
		}
	})

	t.Run("help-output", func(t *testing.T) {
		stdout, _, exit := runSyncExecute(t, "--help")
		if exit != 0 {
			t.Fatalf("tws sync --help must exit 0, got %d", exit)
		}
		for _, phrase := range bannedDocPhrases {
			if strings.Contains(stdout, phrase) {
				t.Errorf("tws sync --help must not contain the banned phrase %q:\n%s", phrase, stdout)
			}
		}
	})
}

package internal

import (
	"bytes"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
)

const InjectDir = "inject"

const injectGitPathReadCap = 4096

// ErrInjectWorktreeNotFound identifies an absent materialized worktree without
// conflating it with an existing path that is not a valid linked worktree.
var ErrInjectWorktreeNotFound = errors.New("inject worktree not found")

// InjectPath returns the inject directory path for a feature.
func InjectPath(featurePath string) string {
	return filepath.Join(featurePath, InjectDir)
}

// InjectFiles symlinks all files from the feature's inject/ directory
// into the target worktree. injectInto is a relative subdirectory within
// the worktree (empty string or "." means worktree root).
// Uses relative symlinks. Skips existing files.
func InjectFiles(featurePath, worktreePath, injectInto string) error {
	injectDir := InjectPath(featurePath)

	if _, err := os.Stat(injectDir); os.IsNotExist(err) {
		return nil // no inject dir, nothing to do
	}

	targetBase := worktreePath
	if injectInto != "" && injectInto != "." {
		targetBase = filepath.Join(worktreePath, injectInto)
		if err := os.MkdirAll(targetBase, 0755); err != nil {
			return fmt.Errorf("could not create inject target %s: %w", targetBase, err)
		}
	}

	return filepath.Walk(injectDir, func(srcPath string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}

		relPath, err := filepath.Rel(injectDir, srcPath)
		if err != nil {
			return err
		}

		if relPath == "." {
			return nil
		}

		destPath := filepath.Join(targetBase, relPath)

		if info.IsDir() {
			return os.MkdirAll(destPath, 0755)
		}

		if _, err := os.Lstat(destPath); err == nil {
			return nil
		}

		relTarget, err := filepath.Rel(filepath.Dir(destPath), srcPath)
		if err != nil {
			return fmt.Errorf("could not compute relative path: %w", err)
		}

		return os.Symlink(relTarget, destPath)
	})
}

type injectWorktreeTarget struct {
	Name string
	Path string
}

type injectStackEntry struct {
	Name     string
	Path     string
	Archived bool
}

// ResolveInjectWorktree resolves and verifies one logical external worktree.
// stack.yaml is authoritative when present; otherwise the explicit logical
// path is accepted only when it is a verified linked Git worktree root.
func ResolveInjectWorktree(featurePath, name string) (string, error) {
	entries, hasStack, err := injectStackEntries(featurePath)
	if err != nil {
		return "", err
	}
	if hasStack {
		for _, entry := range entries {
			if entry.Name != name {
				continue
			}
			if entry.Archived {
				return "", fmt.Errorf("worktree %q is archived", name)
			}
			if err := verifyInjectWorktree(featurePath, entry.Path); err != nil {
				return "", err
			}
			return entry.Path, nil
		}
		return "", ErrInjectWorktreeNotFound
	}

	path, err := injectWorktreePath(featurePath, name)
	if err != nil {
		return "", err
	}
	if err := verifyInjectWorktree(featurePath, path); err != nil {
		return "", err
	}
	return path, nil
}

// InjectFilesForFeature re-syncs inject/ into every materialized active
// worktree for a feature. Targets are validated before the first write and
// processed in deterministic logical-name order.
func InjectFilesForFeature(featurePath, injectInto string) (int, error) {
	targets, err := discoverInjectWorktrees(featurePath)
	if err != nil {
		return 0, err
	}

	count := 0
	var injectErrs []error
	for _, target := range targets {
		if err := InjectFiles(featurePath, target.Path, injectInto); err != nil {
			injectErrs = append(injectErrs, fmt.Errorf("inject failed for %s: %w", target.Name, err))
			continue
		}
		count++
	}
	return count, errors.Join(injectErrs...)
}

func discoverInjectWorktrees(featurePath string) ([]injectWorktreeTarget, error) {
	entries, hasStack, err := injectStackEntries(featurePath)
	if err != nil {
		return nil, err
	}
	if !hasStack {
		return discoverLegacyInjectWorktrees(featurePath)
	}

	targets := make([]injectWorktreeTarget, 0, len(entries))
	seenPaths := make(map[string]string)
	for _, entry := range entries {
		if entry.Archived {
			continue
		}
		err := verifyInjectWorktree(featurePath, entry.Path)
		if errors.Is(err, ErrInjectWorktreeNotFound) {
			continue
		}
		if err != nil {
			return nil, fmt.Errorf("worktree %q: %w", entry.Name, err)
		}
		canonicalPath := canonicalize(entry.Path)
		if previous, ok := seenPaths[canonicalPath]; ok {
			return nil, fmt.Errorf("worktrees %q and %q resolve to the same path %s", previous, entry.Name, canonicalPath)
		}
		seenPaths[canonicalPath] = entry.Name
		targets = append(targets, injectWorktreeTarget{Name: entry.Name, Path: entry.Path})
	}
	sort.Slice(targets, func(i, j int) bool {
		return targets[i].Name < targets[j].Name
	})
	return targets, nil
}

func injectStackEntries(featurePath string) ([]injectStackEntry, bool, error) {
	stackPath := StackPath(featurePath)
	info, err := os.Lstat(stackPath)
	if errors.Is(err, fs.ErrNotExist) {
		return nil, false, nil
	}
	if err != nil {
		return nil, false, fmt.Errorf("reading %s: %w", stackPath, err)
	}
	if !info.Mode().IsRegular() {
		return nil, true, fmt.Errorf("reading %s: stack metadata must be a regular file", stackPath)
	}
	stack, err := LoadStack(featurePath)
	if err != nil {
		return nil, true, fmt.Errorf("reading %s: %w", stackPath, err)
	}

	entries := make([]injectStackEntry, 0, len(stack.Branches))
	seenNames := make(map[string]bool)
	for _, branch := range stack.Branches {
		if seenNames[branch.Name] {
			return nil, true, fmt.Errorf("stack contains duplicate worktree name %q", branch.Name)
		}
		seenNames[branch.Name] = true
		path, err := injectWorktreePath(featurePath, branch.Name)
		if err != nil {
			return nil, true, fmt.Errorf("worktree %q: %w", branch.Name, err)
		}
		entries = append(entries, injectStackEntry{
			Name:     branch.Name,
			Path:     path,
			Archived: branch.Archived,
		})
	}
	sort.Slice(entries, func(i, j int) bool {
		return entries[i].Name < entries[j].Name
	})
	return entries, true, nil
}

func injectWorktreePath(featurePath, name string) (string, error) {
	if name == "" {
		return "", fmt.Errorf("logical worktree name cannot be empty")
	}
	if filepath.IsAbs(name) || filepath.VolumeName(name) != "" || strings.Contains(name, "\\") {
		return "", fmt.Errorf("logical worktree name %q is not a safe relative path", name)
	}
	clean := filepath.Clean(name)
	if clean != name || clean == "." || clean == ".." || strings.HasPrefix(clean, ".."+string(filepath.Separator)) {
		return "", fmt.Errorf("logical worktree name %q is not a safe relative path", name)
	}
	return filepath.Join(featurePath, "worktrees", clean), nil
}

func discoverLegacyInjectWorktrees(featurePath string) ([]injectWorktreeTarget, error) {
	worktreesRoot := filepath.Join(featurePath, "worktrees")
	info, err := os.Lstat(worktreesRoot)
	if errors.Is(err, fs.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("reading worktrees directory %s: %w", worktreesRoot, err)
	}
	if info.Mode()&os.ModeSymlink != 0 || !info.IsDir() {
		return nil, fmt.Errorf("worktrees path %s is not a directory", worktreesRoot)
	}

	var targets []injectWorktreeTarget
	err = filepath.WalkDir(worktreesRoot, func(path string, entry fs.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if path == worktreesRoot {
			return nil
		}
		if entry.Type()&os.ModeSymlink != 0 {
			if entry.IsDir() {
				return filepath.SkipDir
			}
			return nil
		}
		if !entry.IsDir() {
			return nil
		}

		markerInfo, markerErr := os.Lstat(filepath.Join(path, ".git"))
		if errors.Is(markerErr, fs.ErrNotExist) {
			return nil
		}
		if markerErr != nil {
			return markerErr
		}
		if !markerInfo.Mode().IsRegular() {
			return filepath.SkipDir
		}
		if err := verifyInjectWorktree(featurePath, path); err != nil {
			return fmt.Errorf("legacy worktree %s: %w", path, err)
		}
		name, err := filepath.Rel(worktreesRoot, path)
		if err != nil {
			return err
		}
		targets = append(targets, injectWorktreeTarget{Name: name, Path: path})
		return filepath.SkipDir
	})
	if err != nil {
		return nil, fmt.Errorf("discovering legacy worktrees under %s: %w", worktreesRoot, err)
	}
	sort.Slice(targets, func(i, j int) bool {
		return targets[i].Name < targets[j].Name
	})
	return targets, nil
}

func verifyInjectWorktree(featurePath, path string) error {
	worktreesRoot := filepath.Join(featurePath, "worktrees")
	if err := rejectInjectPathSymlinks(worktreesRoot, path); err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return fmt.Errorf("%w: %s", ErrInjectWorktreeNotFound, path)
		}
		return err
	}

	rootPath, err := filepath.EvalSymlinks(worktreesRoot)
	if err != nil {
		return err
	}
	targetPath, err := filepath.EvalSymlinks(path)
	if err != nil {
		return err
	}
	rel, err := filepath.Rel(rootPath, targetPath)
	if err != nil || rel == "." || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return fmt.Errorf("worktree path %s escapes %s", path, worktreesRoot)
	}

	marker := filepath.Join(path, ".git")
	markerInfo, err := os.Lstat(marker)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return fmt.Errorf("%s is not a linked Git worktree", path)
		}
		return fmt.Errorf("reading Git marker %s: %w", marker, err)
	}
	if !markerInfo.Mode().IsRegular() {
		return fmt.Errorf("%s is not a linked Git worktree", path)
	}

	gitDir, err := resolveInjectGitDir(path, marker)
	if err != nil {
		return err
	}
	if err := verifyInjectGitBackpointer(path, marker, gitDir); err != nil {
		return err
	}
	if err := verifyInjectCommonDir(path, gitDir); err != nil {
		return err
	}

	topLevel, err := gitPathOutput(path, "rev-parse", "--show-toplevel")
	if err != nil {
		return fmt.Errorf("%s is not a valid Git worktree: %w", path, err)
	}
	if canonicalize(topLevel) != canonicalize(path) {
		return fmt.Errorf("Git worktree root for %s is %s", path, topLevel)
	}
	if err := verifyInjectWorktreeRegistration(path); err != nil {
		return err
	}
	return nil
}

func resolveInjectGitDir(worktreePath, markerPath string) (string, error) {
	pointer, err := readInjectGitPathFile(markerPath)
	if err != nil {
		return "", fmt.Errorf("reading Git marker %s: %w", markerPath, err)
	}
	gitDir, ok := strings.CutPrefix(pointer, "gitdir: ")
	if !ok || gitDir == "" {
		return "", fmt.Errorf("malformed gitdir pointer in %s", markerPath)
	}
	if !filepath.IsAbs(gitDir) {
		gitDir = filepath.Join(worktreePath, gitDir)
	}
	gitDir = filepath.Clean(gitDir)
	info, err := os.Lstat(gitDir)
	if err != nil {
		return "", fmt.Errorf("resolving Git directory for %s: %w", worktreePath, err)
	}
	if info.Mode()&os.ModeSymlink != 0 || !info.IsDir() {
		return "", fmt.Errorf("Git directory %s for %s is not a directory", gitDir, worktreePath)
	}
	return gitDir, nil
}

func verifyInjectGitBackpointer(worktreePath, markerPath, gitDir string) error {
	backpointerPath := filepath.Join(gitDir, "gitdir")
	backpointer, err := readInjectGitPathFile(backpointerPath)
	if err != nil {
		return fmt.Errorf("reading Git worktree backpointer for %s: %w", worktreePath, err)
	}
	if !filepath.IsAbs(backpointer) {
		backpointer = filepath.Join(gitDir, backpointer)
	}
	backpointer = filepath.Clean(backpointer)
	info, err := os.Lstat(backpointer)
	if err != nil {
		return fmt.Errorf("resolving Git worktree backpointer for %s: %w", worktreePath, err)
	}
	if info.Mode()&os.ModeSymlink != 0 || !info.Mode().IsRegular() {
		return fmt.Errorf("Git worktree backpointer for %s does not name a regular .git file", worktreePath)
	}
	if canonicalize(backpointer) != canonicalize(markerPath) {
		return fmt.Errorf("Git worktree backpointer for %s names %s", worktreePath, backpointer)
	}
	return nil
}

func verifyInjectCommonDir(worktreePath, gitDir string) error {
	commonDirPath := filepath.Join(gitDir, "commondir")
	commonDir, err := readInjectGitPathFile(commonDirPath)
	if err != nil {
		return fmt.Errorf("reading Git common directory for %s: %w", worktreePath, err)
	}
	if !filepath.IsAbs(commonDir) {
		commonDir = filepath.Join(gitDir, commonDir)
	}
	commonDir = filepath.Clean(commonDir)
	info, err := os.Lstat(commonDir)
	if err != nil {
		return fmt.Errorf("resolving Git common directory for %s: %w", worktreePath, err)
	}
	if info.Mode()&os.ModeSymlink != 0 || !info.IsDir() {
		return fmt.Errorf("Git common directory %s for %s is not a directory", commonDir, worktreePath)
	}
	return nil
}

func verifyInjectWorktreeRegistration(worktreePath string) error {
	cmd := exec.Command("git", "-C", worktreePath, "worktree", "list", "--porcelain", "-z")
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	out, err := cmd.Output()
	if err != nil {
		message := strings.TrimSpace(stderr.String())
		if message == "" {
			return fmt.Errorf("listing registered Git worktrees for %s: %w", worktreePath, err)
		}
		return fmt.Errorf("listing registered Git worktrees for %s: %w: %s", worktreePath, err, message)
	}

	want := canonicalize(worktreePath)
	inBlock := false
	found := false
	for _, field := range bytes.Split(out, []byte{0}) {
		if len(field) == 0 {
			inBlock = false
			continue
		}
		if bytes.HasPrefix(field, []byte("worktree ")) {
			if inBlock {
				return fmt.Errorf("malformed Git worktree inventory for %s: duplicate worktree field", worktreePath)
			}
			rawPath := string(bytes.TrimPrefix(field, []byte("worktree ")))
			if rawPath == "" {
				return fmt.Errorf("malformed Git worktree inventory for %s: empty worktree path", worktreePath)
			}
			inBlock = true
			if canonicalize(rawPath) == want {
				found = true
			}
			continue
		}
		if !inBlock {
			return fmt.Errorf("malformed Git worktree inventory for %s: field before worktree path", worktreePath)
		}
	}
	if !found {
		return fmt.Errorf("%s is not registered in the Git worktree inventory", worktreePath)
	}
	return nil
}

func readInjectGitPathFile(path string) (string, error) {
	info, err := os.Lstat(path)
	if err != nil {
		return "", err
	}
	if info.Mode()&os.ModeSymlink != 0 || !info.Mode().IsRegular() {
		return "", fmt.Errorf("%s is not a regular file", path)
	}
	if info.Size() > injectGitPathReadCap {
		return "", fmt.Errorf("%s exceeds %d bytes", path, injectGitPathReadCap)
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return "", err
	}
	// Git control files accept CRLF; command stdout may instead contain a
	// pathname ending in CR followed by its single LF terminator.
	if bytes.HasSuffix(data, []byte("\r\n")) {
		data = data[:len(data)-2]
	}
	return injectGitPath(data)
}

func injectGitPath(data []byte) (string, error) {
	if len(data) == 0 {
		return "", errors.New("empty Git path")
	}
	if bytes.IndexByte(data, 0) >= 0 {
		return "", errors.New("Git path contains NUL")
	}
	if data[len(data)-1] == '\n' {
		data = data[:len(data)-1]
	}
	if len(data) == 0 {
		return "", errors.New("empty Git path")
	}
	return string(data), nil
}

func rejectInjectPathSymlinks(root, target string) error {
	rootInfo, err := os.Lstat(root)
	if err != nil {
		return err
	}
	if rootInfo.Mode()&os.ModeSymlink != 0 || !rootInfo.IsDir() {
		return fmt.Errorf("worktrees path %s is not a directory", root)
	}

	rel, err := filepath.Rel(root, target)
	if err != nil || rel == "." || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return fmt.Errorf("worktree path %s escapes %s", target, root)
	}
	current := root
	for _, part := range strings.Split(rel, string(filepath.Separator)) {
		current = filepath.Join(current, part)
		info, err := os.Lstat(current)
		if err != nil {
			return err
		}
		if info.Mode()&os.ModeSymlink != 0 {
			return fmt.Errorf("worktree path %s contains symlink component %s", target, current)
		}
	}
	return nil
}

func gitPathOutput(path string, args ...string) (string, error) {
	cmd := exec.Command("git", append([]string{"-C", path}, args...)...)
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	out, err := cmd.Output()
	if err != nil {
		message := strings.TrimSpace(stderr.String())
		if message == "" {
			return "", err
		}
		return "", fmt.Errorf("%w: %s", err, message)
	}
	return injectGitPath(out)
}

// ResolveInjectInto returns the inject target from the flag or config.
func ResolveInjectInto(flagValue string) string {
	if flagValue != "" {
		return flagValue
	}
	cfg := LoadConfig()
	return cfg.InjectInto
}

package internal

import (
	"os"
	"path/filepath"
	"testing"
)

func TestInjectGitPathPreservesMeaningfulWhitespace(t *testing.T) {
	tests := []struct {
		name string
		data string
		want string
	}{
		{name: "trailing spaces", data: "/tmp/review/entry  \n", want: "/tmp/review/entry  "},
		{name: "tab", data: "/tmp/review/\tentry\n", want: "/tmp/review/\tentry"},
		{name: "internal newline", data: "/tmp/review/line\nentry\n", want: "/tmp/review/line\nentry"},
		{name: "trailing carriage return", data: "/tmp/review/entry \r\n", want: "/tmp/review/entry \r"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			got, err := injectGitPath([]byte(tc.data))
			if err != nil {
				t.Fatal(err)
			}
			if got != tc.want {
				t.Fatalf("path = %q, want %q", got, tc.want)
			}
		})
	}
}

func TestInjectGitPathFileAcceptsCRLF(t *testing.T) {
	path := filepath.Join(t.TempDir(), "gitdir")
	if err := os.WriteFile(path, []byte("/tmp/review/entry \r\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	got, err := readInjectGitPathFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if got != "/tmp/review/entry " {
		t.Fatalf("Git control file path = %q, want CRLF terminator removed", got)
	}
}

func TestGitPathOutputSeparatesStderr(t *testing.T) {
	binDir := t.TempDir()
	gitPath := filepath.Join(binDir, "git")
	script := "#!/bin/sh\nprintf '/tmp/review/entry  \\n'\nprintf 'warning: diagnostic only\\n' >&2\n"
	if err := os.WriteFile(gitPath, []byte(script), 0755); err != nil {
		t.Fatal(err)
	}
	t.Setenv("PATH", binDir+string(os.PathListSeparator)+os.Getenv("PATH"))

	got, err := gitPathOutput("/ignored", "rev-parse", "--show-toplevel")
	if err != nil {
		t.Fatal(err)
	}
	if got != "/tmp/review/entry  " {
		t.Fatalf("path = %q, want trailing spaces preserved and stderr excluded", got)
	}
}
